 */

/*
 * Offset of keylog_callback pointer in SSL struct
 *
 * Derived from dissassembly of ssl_log_secret in ssl_lib.c on iOS 12.4.3
 * 
 * 0000000181d4e214         sub        sp, sp, #0x60
 * 0000000181d4e218         stp        x22, x21, [sp, #0x30]
 * 0000000181d4e21c         stp        x20, x19, [sp, #0x40]
 * 0000000181d4e220         stp        x29, x30, [sp, #0x50]
 * 0000000181d4e224         add        x29, sp, #0x50
 * 0000000181d4e228         ldr        x8, [x0, #0x68]
 * 0000000181d4e22c         ldr        x8, [x8, #0x2a8]         ; Offset of keylog_callback pointer
 * 0000000181d4e230         cbz        x8, loc_181d4e338
 * 
 * TODO: Is it possible to make this less fragile?
 */
var CALLBACK_OFFSET = 0x2b8; // iOS 14.x offset

// Logging function, reads null terminated string from address in line
function key_logger(ssl, line) {
    console.log(new NativePointer(line).readCString());
}

// Wrap key_logger JS function in NativeCallback
var key_log_callback = new NativeCallback(key_logger, 'void', ['pointer', 'pointer']);

/*
 * SSL_CTX_set_keylog_callback isn't implemented in iOS version of boringssl
 *
 * Hook SSL_CTX_set_info_callback as it can access SSL_CTX and 
 * directly set SSL_CTX->keylog_callback to address of logging callback above
 */
var SSL_CTX_set_info_callback = Module.findExportByName("libboringssl.dylib", "SSL_CTX_set_info_callback");

Interceptor.attach(SSL_CTX_set_info_callback, {
    onEnter: function (args) {
        var ssl = new NativePointer(args[0]);
        var callback = new NativePointer(ssl).add(CALLBACK_OFFSET);

        callback.writePointer(key_log_callback);
    }
});

/*
 * Frida SSL/TLS Tracer
 * This script hooks various SSL/TLS and socket-related functions to help identify
 * where SSL/TLS operations are performed in native code.
 */

// Helper function to print stack traces with module information
function getStackTraceWithModules() {
    let result = "";
    try {
        throw new Error();
    } catch (e) {
        const stack = Thread.backtrace(e.context, Backtracer.ACCURATE)
            .map(DebugSymbol.fromAddress)
            .filter(function(symbol) {
                return symbol.name !== null && symbol.name.indexOf("frida") === -1;
            });

        for (let i = 0; i < stack.length; i++) {
            result += `${i}\t${stack[i].address} ${stack[i].moduleName}!${stack[i].name || "???"}\n`;
        }
    }
    return result;
}

// Function to get module details for an address
function getModuleForAddress(addr) {
    try {
        const module = Process.findModuleByAddress(addr);
        if (module) {
            return `${module.name} (${module.base}-${module.base.add(module.size)})`;
        }
    } catch (e) {}
    return "Unknown module";
}

// Hook OpenSSL functions
function hookOpenSSL() {
    console.log("[*] Hooking OpenSSL functions...");

    const sslHandshakeFuncs = [
        "SSL_connect",
        "SSL_do_handshake",
        "SSL_accept",
        "SSL_CTX_new",
        "TLS_method",
        "TLS_client_method",
        "SSL_new"
    ];

    sslHandshakeFuncs.forEach(funcName => {
        const func = Module.findExportByName(null, funcName);
        if (func) {
            console.log(`[+] Found ${funcName} at ${func}`);
            Interceptor.attach(func, {
                onEnter: function(args) {
                    console.log(`\n[+] Called ${funcName}`);
                    console.log(`[+] Module: ${getModuleForAddress(this.returnAddress)}`);
                    console.log("[+] Stack trace:");
                    console.log(getStackTraceWithModules());
                }
            });
        } else {
            console.log(`[-] Function ${funcName} not found`);
        }
    });
}

// Hook BoringSSL functions (used in some Android apps and Chrome)
function hookBoringSSL() {
    console.log("[*] Hooking BoringSSL functions...");

    const boringFuncs = [
        "SSL_do_handshake",
        "SSL_connect",
        "SSL_CTX_new",
        "SSL_library_init"
    ];

    boringFuncs.forEach(funcName => {
        const func = Module.findExportByName(null, funcName);
        if (func) {
            console.log(`[+] Found ${funcName} at ${func}`);
            Interceptor.attach(func, {
                onEnter: function(args) {
                    console.log(`\n[+] Called ${funcName}`);
                    console.log(`[+] Module: ${getModuleForAddress(this.returnAddress)}`);
                    console.log("[+] Stack trace:");
                    console.log(getStackTraceWithModules());
                }
            });
        }
    });
}

// Hook GnuTLS functions
function hookGnuTLS() {
    console.log("[*] Hooking GnuTLS functions...");

    const gnuTlsFuncs = [
        "gnutls_handshake",
        "gnutls_init",
        "gnutls_credentials_set"
    ];

    gnuTlsFuncs.forEach(funcName => {
        const func = Module.findExportByName(null, funcName);
        if (func) {
            console.log(`[+] Found ${funcName} at ${func}`);
            Interceptor.attach(func, {
                onEnter: function(args) {
                    console.log(`\n[+] Called ${funcName}`);
                    console.log(`[+] Module: ${getModuleForAddress(this.returnAddress)}`);
                    console.log("[+] Stack trace:");
                    console.log(getStackTraceWithModules());
                }
            });
        }
    });
}

// Hook socket-related functions
function hookSocketFunctions() {
    console.log("[*] Hooking socket-related functions...");

    const socketFuncs = [
        "socket",
        "connect",
        "send",
        "recv",
        "SSL_write",
        "SSL_read"
    ];

    socketFuncs.forEach(funcName => {
        const func = Module.findExportByName(null, funcName);
        if (func) {
            console.log(`[+] Found ${funcName} at ${func}`);
            Interceptor.attach(func, {
                onEnter: function(args) {
                    // Only log for non-loopback connections to reduce noise
                    if (funcName === "connect") {
                        const sockAddr = args[1];
                        const sockAddrIn = sockAddr.add(2);
                        const port = Memory.readU16(sockAddrIn);
                        const ip = Memory.readU32(sockAddrIn.add(2));
                        // Skip if it's localhost (127.0.0.1)
                        if (ip === 0x0100007f) {
                            return;
                        }
                    }

                    console.log(`\n[+] Called ${funcName}`);
                    console.log(`[+] Module: ${getModuleForAddress(this.returnAddress)}`);
                    // Log additional details for specific functions
                    if (funcName === "SSL_write" || funcName === "SSL_read") {
                        console.log(`[+] SSL context: ${args[0]}`);
                        if (args[1] != null) {
                            try {
                                const data = Memory.readByteArray(args[1], args[2].toInt32() > 100 ? 100 : args[2].toInt32());
                                console.log(`[+] Data preview: ${hexdump(data, { length: 32 })}`);
                            } catch (e) {
                                console.log(`[!] Error reading data: ${e}`);
                            }
                        }
                    }

                    console.log("[+] Stack trace:");
                    console.log(getStackTraceWithModules());
                }
            });
        } else {
            console.log(`[-] Function ${funcName} not found`);
        }
    });
}

// Hook platform-specific libraries

// iOS/macOS Security framework
function hookAppleSecurity() {
    console.log("[*] Checking for Apple Security framework...");

    const securityFunctions = [
        "SSLHandshake",
        "SSLSetConnection",
        "SSLCreateContext",
        "SecureTransportProtocol"
    ];

    securityFunctions.forEach(funcName => {
        const func = Module.findExportByName("Security", funcName) ||
            Module.findExportByName("libSystem.B.dylib", funcName);
        if (func) {
            console.log(`[+] Found ${funcName} at ${func}`);
            Interceptor.attach(func, {
                onEnter: function(args) {
                    console.log(`\n[+] Called ${funcName}`);
                    console.log(`[+] Module: ${getModuleForAddress(this.returnAddress)}`);
                    console.log("[+] Stack trace:");
                    console.log(getStackTraceWithModules());
                }
            });
        }
    });
}

// Windows SChannel
function hookSChannel() {
    console.log("[*] Checking for Windows SChannel...");

    const schannelFuncs = [
        "InitializeSecurityContextW",
        "InitializeSecurityContextA",
        "AcquireCredentialsHandleW",
        "AcquireCredentialsHandleA",
        "AcceptSecurityContext"
    ];

    schannelFuncs.forEach(funcName => {
        const func = Module.findExportByName("secur32.dll", funcName) ||
            Module.findExportByName("security.dll", funcName);
        if (func) {
            console.log(`[+] Found ${funcName} at ${func}`);
            Interceptor.attach(func, {
                onEnter: function(args) {
                    console.log(`\n[+] Called ${funcName}`);
                    console.log(`[+] Module: ${getModuleForAddress(this.returnAddress)}`);
                    console.log("[+] Stack trace:");
                    console.log(getStackTraceWithModules());
                }
            });
        }
    });
}

// Custom function to log all loaded modules for reference
function listLoadedModules() {
    console.log("[*] Listing all loaded modules...");
    Process.enumerateModules()
        .sort((a, b) => a.name.localeCompare(b.name))
        .forEach(module => {
            console.log(`[+] ${module.name}: ${module.base}-${module.base.add(module.size)} (Size: ${module.size})`);
        });
}

// Log information about SSL certificates (works with OpenSSL)
function hookCertificateVerification() {
    const x509Funcs = [
        "X509_verify_cert",
        "SSL_CTX_set_verify"
    ];

    x509Funcs.forEach(funcName => {
        const func = Module.findExportByName(null, funcName);
        if (func) {
            console.log(`[+] Found ${funcName} at ${func}`);
            Interceptor.attach(func, {
                onEnter: function(args) {
                    console.log(`\n[+] Called ${funcName} - Certificate verification`);
                    console.log(`[+] Module: ${getModuleForAddress(this.returnAddress)}`);
                    console.log("[+] Stack trace:");
                    console.log(getStackTraceWithModules());

                    if (funcName === "SSL_CTX_set_verify") {
                        console.log(`[+] Verify mode: ${args[1]}`);
                        console.log(`[+] Verify callback: ${args[2]}`);
                    }
                }
            });
        }
    });
}

// Main function to start hooking
function main() {
    console.log("[*] Starting SSL/TLS tracer...");

    // Platform detection (optional)
    const platform = Process.platform;
    console.log(`[*] Detected platform: ${platform}`);

    // List all loaded modules for reference
    listLoadedModules();

    // Hook SSL implementations
    hookOpenSSL();
    hookBoringSSL();
    hookGnuTLS();
    hookCertificateVerification();

    // Hook socket functions
    hookSocketFunctions();

    // Platform-specific hooks
    if (platform === "darwin" || platform === "ios") {
        hookAppleSecurity();
    } else if (platform === "windows") {
        hookSChannel();
    }

    console.log("[*] All hooks installed. Waiting for SSL/TLS operations...");
}

// Start the script
main();

// SSL Pinning Bypass iOS - Frida Script
// Cobertura: SecTrustEvaluate, NSURLSession, BoringSSL
console.log("[*] Iniciando SSL Bypass para iOS...");

const SSL_VERIFY_NONE = 0;

// --- SecTrustEvaluate ---
const trustEvaluate = Module.findExportByName(null, "SecTrustEvaluate");
if (trustEvaluate) {
    Interceptor.replace(trustEvaluate, new NativeCallback(function (trustRef, resultPtr) {
        console.log("[*] SecTrustEvaluate interceptado");
        if (!resultPtr.isNull()) {
            Memory.writeU32(resultPtr, 1); // kSecTrustResultProceed
        }
        return 0; // errSecSuccess
    }, 'int', ['pointer', 'pointer']));
}

const trustEvaluateWithError = Module.findExportByName(null, "SecTrustEvaluateWithError");
if (trustEvaluateWithError) {
    Interceptor.replace(trustEvaluateWithError, new NativeCallback(function (trust, error) {
        console.log("[*] SecTrustEvaluateWithError interceptado");
        return 1; // true
    }, 'bool', ['pointer', 'pointer']));
}

// --- CFNetwork (opcional) ---
const cfSetAllowsAny = Module.findExportByName(null, "CFURLConnectionSetAllowsAnyHTTPSCertificate");
if (cfSetAllowsAny) {
    Interceptor.replace(cfSetAllowsAny, new NativeCallback(function (conn, host) {
        console.log("[*] CFURLConnectionSetAllowsAnyHTTPSCertificate interceptado");
    }, 'void', ['pointer', 'pointer']));
}

// --- BoringSSL (solo si está presente) ---
try {
    const boring = Process.getModuleByName("libboringssl.dylib");
    const setVerifyPtr = boring.findExportByName("SSL_set_custom_verify");
    const getPskPtr = boring.findExportByName("SSL_get_psk_identity");

    if (setVerifyPtr) {
        const SSL_set_custom_verify = new NativeFunction(setVerifyPtr, 'void', ['pointer', 'int', 'pointer']);
        const verifyCallback = new NativeCallback(function (ssl, alert) {
            console.log("[*] SSL verify callback ejecutado");
            return SSL_VERIFY_NONE;
        }, 'int', ['pointer', 'pointer']);

        Interceptor.replace(setVerifyPtr, new NativeCallback(function (ssl, mode, cb) {
            console.log("[*] Reemplazando SSL_set_custom_verify");
            SSL_set_custom_verify(ssl, mode, verifyCallback);
        }, 'void', ['pointer', 'int', 'pointer']));
    }

    if (getPskPtr) {
        Interceptor.replace(getPskPtr, new NativeCallback(function (ssl) {
            console.log("[*] SSL_get_psk_identity interceptado");
            return Memory.allocUtf8String("notarealPSKidentity");
        }, 'pointer', ['pointer']));
    }
} catch (e) {
    console.log("[-] libboringssl.dylib no presente o no cargado");
}

console.log("[+] SSL Bypass cargado correctamente.");

