function print_arg(addr, len = 240, indent = null) {
    var result = "";
    try {
        if (!addr || addr.toInt32() === 0 || addr.isNull())
            return "\n";
        result = "\n" + (hexdump(addr, {
            length: len
        })) + "\n";
    } catch (e) {
        if (e instanceof Error) {
            console.warn("print_arg error:", e.stack);
        }
        result = addr + "\n";
    }
    if (indent != null) {
        result = result.split('\n')
            .map(line => indent + line)
            .join('\n');
    }
    return result;
}

function pointerToInt(ptr) {
    try {
        if (!ptr || ptr.toInt32() === 0 || ptr.isNull())
            return 0;
        return parseInt(ptr.toString());
    } catch (e) {
        if (e instanceof Error) {
            console.warn("pointerToInt error:", e.stack);
        }
        return 0;
    }
}

// Convert buffer to hex string
function bufferToHex(addr, len) {
    if (!addr || addr.isNull() || !len || len === 0) return "";
    try {
        const bytes = new Uint8Array(Memory.readByteArray(addr, len));
        return Array.from(bytes)
            .map(b => b.toString(16).padStart(2, '0'))
            .join('');
    } catch (e) {
        return "";
    }
}

// Convert buffer to base64 string
function bufferToBase64(addr, len) {
    if (!addr || addr.isNull() || !len || len === 0) return "";
    try {
        const bytes = Memory.readByteArray(addr, len);
        const uint8 = new Uint8Array(bytes);
        let binary = '';
        for (let i = 0; i < uint8.length; i++) {
            binary += String.fromCharCode(uint8[i]);
        }
        // Manual base64 encoding
        const b64chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
        let result = '';
        for (let i = 0; i < binary.length; i += 3) {
            const a = binary.charCodeAt(i);
            const b = i + 1 < binary.length ? binary.charCodeAt(i + 1) : 0;
            const c = i + 2 < binary.length ? binary.charCodeAt(i + 2) : 0;

            result += b64chars[a >> 2];
            result += b64chars[((a & 3) << 4) | (b >> 4)];
            result += i + 1 < binary.length ? b64chars[((b & 15) << 2) | (c >> 6)] : '=';
            result += i + 2 < binary.length ? b64chars[c & 63] : '=';
        }
        return result;
    } catch (e) {
        return "";
    }
}

function filterLog(msg, filter) {
    if (filter == null || filter.length == 0) {
        console.log(msg);
    } else {
        var hasFilter = false;
        for (let value of filter) {
            if (value == null || value.length == 0)
                continue;
            hasFilter = true;
            if (msg.indexOf(value) >= 0) {
                console.log(msg);
                return;
            }
        }
        if (!hasFilter) {
            console.log(msg);
        }
    }
}

