            this.log = this.log.concat("[+] Data len: ", printLength, "/", dataInLength, "\n");
            this.log = this.log.concat("[+] Data : \n", "\n");
            this.log = this.log.concat(print_arg(args[6], printLength));
            this.dataOut = args[8];
            this.dataOutLength = args[10];
        },
        onLeave: function(retval) {
            if (!this.enable)
